// Checkout handler with revenue event logging
const { logRevenueEvent } = require('./revenueLogger');

async function handleCheckout(req, res) {
  try {
    const { paymentIntentId, amount, currency, customerId } = req.body;
    // Process payment...
    // On success:
    await logRevenueEvent({
      eventType: 'paidEvent',
      paymentIntentId,
      amount,
      currency,
      customerId,
      timestamp: new Date().toISOString()
    });
    res.status(200).json({ success: true });
  } catch (err) {
    console.error('Checkout error:', err);
    res.status(500).json({ error: 'Checkout failed' });
  }
}

module.exports = { handleCheckout };
